import java.util.*;

class Solution {
  public long minimumTotalCost(int[] nums1, int[] nums2) {
    long cost = 0;
    int same = 0, dominant = -1, dominantCount = 0;
    Map<Integer, Integer> frequency = new HashMap<>();
    for (int i = 0; i < nums1.length; i++)
      if (nums1[i] == nums2[i]) {
        cost += i;
        same++;
        int count = frequency.merge(nums1[i], 1, Integer::sum);
        if (count > dominantCount) {
          dominantCount = count;
          dominant = nums1[i];
        }
      }
    int needed = Math.max(0, 2 * dominantCount - same);
    if (needed == 0) return cost;
    for (int i = 0; i < nums1.length && needed > 0; i++) {
      if (nums1[i] != nums2[i] && nums1[i] != dominant && nums2[i] != dominant) {
        cost += i;
        needed--;
      }
    }
    return needed == 0 ? cost : -1;
  }
}
